import os
import requests
from agents import function_tool
SLACK_URL = 'https://slack.com/api/chat.postMessage'
DRAFT_DIR = '/tmp/note_drafts'

def _format_message(title, body):
    trimmed = body if len(body) <= 3000 else body[:3000] + '...'
    return f'*{title}*\n{trimmed}'

@function_tool
def post_note_to_slack(channel: str, note_title: str, note_body: str) -> str:
    headers = {'Authorization': 'Bearer ' + os.environ['SLACK_BOT_TOKEN']}
    payload = {'channel': channel, 'text': _format_message(note_title, note_body)}
    r = requests.post(SLACK_URL, json=payload, headers=headers, timeout=15)
    r.raise_for_status()
    data = r.json()
    if not data.get('ok'):
        return 'Slack error: ' + str(data.get('error'))
    # Remove the local draft file for this note once it has been posted
    draft_path = os.path.join(DRAFT_DIR, os.path.basename(note_title) + '.md')
    if os.path.isfile(draft_path):
        os.remove(draft_path)
    return 'Posted to ' + channel + ' at ' + data['ts']
